void mainImage(out vec4 fragColor, in vec2 fragCoord) 
{
    // Normalize pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    // Center the coordinates around (0,0) and adjust for the aspect ratio
    vec2 centered = uv - 0.5;
    if (iResolution.y > 0.0) {
        centered.x *= iResolution.x / iResolution.y;
    }

    // Convert to polar coordinates
    float angle = atan(centered.y, centered.x);
    float radius = length(centered);

    // Create a swirling effect using sine waves influenced by time and angle
    float swirl = sin(10.0 * radius - iTime * 2.0 + angle * 5.0);

    // Generate a color palette using cosine waves for a dynamic color shift
    vec3 color = 0.5 + 0.5 * cos(iTime + radius * 15.0 + vec3(0.0, 2.0, 4.0));

    // Modulate color by swirl effect
    color *= 0.5 + 0.5 * swirl;

    // Apply a vignette effect for focus
    float vignette = smoothstep(0.9, 0.3, radius);
    color *= vignette;

    fragColor = vec4(color, 1.0);
}
